-- Organization ownership boundary and active membership relation. Organization
-- IDs are generated by the application and slugs are immutable URL identity.

CREATE TABLE organizations (
    id uuid PRIMARY KEY,
    slug text NOT NULL,
    display_name text NOT NULL,
    status text NOT NULL DEFAULT 'active',
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    archived_at timestamptz,
    lock_version bigint NOT NULL DEFAULT 1,
    CONSTRAINT organizations_id_v7_check
        CHECK (
            substring(id::text FROM 15 FOR 1) = '7'
            AND substring(id::text FROM 20 FOR 1) IN ('8', '9', 'a', 'b')
        ),
    CONSTRAINT organizations_slug_unique UNIQUE (slug),
    CONSTRAINT organizations_slug_check
        CHECK (
            char_length(slug) BETWEEN 1 AND 63
            AND slug ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'
        ),
    CONSTRAINT organizations_display_name_check
        CHECK (
            display_name = btrim(display_name)
            AND display_name !~ '[[:cntrl:]]'
            AND char_length(display_name) BETWEEN 1 AND 200
        ),
    CONSTRAINT organizations_status_check
        CHECK (status IN ('active', 'archived')),
    CONSTRAINT organizations_lifecycle_check
        CHECK (
            (status = 'active' AND archived_at IS NULL)
            OR (status = 'archived' AND archived_at IS NOT NULL)
        ),
    CONSTRAINT organizations_timestamps_check
        CHECK (
            updated_at >= created_at
            AND (archived_at IS NULL OR archived_at >= created_at)
            AND (archived_at IS NULL OR updated_at >= archived_at)
        ),
    CONSTRAINT organizations_lock_version_check
        CHECK (lock_version BETWEEN 1 AND 9223372036854775806)
);

CREATE INDEX organizations_active_slug_idx
    ON organizations (slug)
    WHERE status = 'active';

CREATE TABLE organization_memberships (
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (organization_id, user_id),
    CONSTRAINT organization_memberships_organization_fk
        FOREIGN KEY (organization_id) REFERENCES organizations (id) ON DELETE RESTRICT,
    CONSTRAINT organization_memberships_user_fk
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT organization_memberships_role_check
        CHECK (role IN ('owner', 'member')),
    CONSTRAINT organization_memberships_timestamps_check
        CHECK (updated_at >= created_at)
);

CREATE INDEX organization_memberships_user_idx
    ON organization_memberships (user_id, organization_id);
CREATE INDEX organization_memberships_owner_idx
    ON organization_memberships (organization_id, user_id)
    WHERE role = 'owner';

CREATE OR REPLACE FUNCTION enforce_organization_immutable_fields()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id
        OR NEW.slug IS DISTINCT FROM OLD.slug
        OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
        RAISE EXCEPTION 'organization immutable fields cannot change'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.lock_version <> OLD.lock_version + 1 THEN
        RAISE EXCEPTION 'organization update must advance lock version exactly once'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER organizations_immutable_fields
    BEFORE UPDATE ON organizations
    FOR EACH ROW
    EXECUTE FUNCTION enforce_organization_immutable_fields();
